# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: gather
def gather(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return gather(digest(fold(shape(intake(raw)))))

